// statusCacheSafe reports whether t's handler is guaranteed to neither write
// tracked files nor stage anything for the duration of the handler, which is the
// precondition for reusing one worktree status across it (see
// gitrepo.WithStatusCache).
//
// This is a closed allowlist and must stay one. Post-agent handlers — TurnEnd,
// SubagentEnd — run after the agent has edited files, and DetectFileChanges
// there must observe those edits. Before adding an event, check that its handler
// performs no tracked-file write between its first and last status read;
// TurnStart only qualifies because EnsureSetup (which can rewrite the tracked
// .entire/.gitignore) was hoisted above its first read.
//
// Every event is listed explicitly rather than folded into the default so the
// exhaustive linter fails the build when a new EventType is added, forcing that
// review to happen. The default stays as a belt-and-braces deny.
func statusCacheSafe(t agent.EventType) bool {
	switch t {
	case agent.TurnStart:
		return true
	case agent.SessionStart, agent.TurnEnd, agent.Compaction, agent.SessionEnd,
		agent.SubagentStart, agent.SubagentEnd, agent.ModelUpdate, agent.ToolUse:
---
	ctx = strategy.WithSessionLockWait(ctx, turnStartSessionLockWait)

	// Fill model from hint file if the agent didn't provide it on this hook
	if event.Model == "" {
		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
			event.Model = hint
			logging.Debug(logCtx, "loaded model from hint file",
				slog.String("model", hint))
		}
	}

	// Strategy setup runs before the first worktree-status read below.
	// EnsureEntireGitignore can append entries to .entire/.gitignore, which is
	// tracked, and the dispatcher has already installed a status cache for this
	// event (see statusCacheSafe). The cache fills on first read rather than at
	// install, so doing this write first keeps every cached read consistent with
	// the worktree. Moving this back below CapturePrePromptState would reintroduce
	// a tracked-file write between two cached reads.
	_, setupSpan := perf.Start(ctx, "ensure_setup")
	if err := strategy.EnsureSetup(ctx); err != nil {
		logging.Warn(logCtx, "failed to ensure strategy setup",
			slog.String("error", err.Error()))
	}
	setupSpan.End()

	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)

		Reason:               telemetry.PolicyBlockedReasonUnsupported,
		Outcome:              telemetry.PolicyBlockedOutcomeSkipped,
		CheckpointVersion:    policy.CheckpointVersion,
		CheckpointMinVersion: policy.CheckpointMinVersion,
	})
	return true
}

// skipUnreadableCheckpointPolicy warns, notifies the user, and reports the
// policy-blocked telemetry event for a hook whose checkpoint policy could not be
// read. It always returns true so callers skip Entire checkpoint work.
func (g *gitHookContext) skipUnreadableCheckpointPolicy(err error) bool {
	logging.Warn(g.ctx, "checkpoint policy read failed; skipping git hook",
		slog.String("error", err.Error()))
	if interactive.CanPromptInteractively() {
		fmt.Fprintf(os.Stderr, "[entire] Could not read checkpoint policy; skipping Entire checkpoint work: %v\n", err)
	}
	emitCheckpointPolicyBlocked(g.ctx, telemetry.CheckpointPolicyBlockedEvent{
		Hook:     g.hookName,
		HookType: telemetry.PolicyBlockedHookTypeGit,
		Reason:   telemetry.PolicyBlockedReasonUnreadable,
		Outcome:  telemetry.PolicyBlockedOutcomeSkipped,
	})
	return true
}

// initHookLogging initializes logging for hooks by finding the most recent session.
// Returns a cleanup function that should be deferred.
// If Entire is not active for this repo (repo-level setup or the user-global
// tier), returns a no-op to avoid creating files.
func initHookLogging(ctx context.Context) func() {
	// Don't create any files if Entire is not active for this repo
	// (repo-level setup or the user-global tier). This is checked here as
	// defense-in-depth (also checked in PersistentPreRunE); both layers of
	// the gate must use the same predicate, settings.IsActiveForRepo, so
	// global-mode repos get hook logging and redaction configuration too.
	if !settings.IsActiveForRepo(ctx) {
		return func() {}
	}

	// Set up log level getter so logging can read from settings
	logging.SetLogLevelGetter(GetLogLevel)

	// Read session ID for the slog attribute (empty string is fine - log file is fixed)
	sessionID := strategy.FindMostRecentSession(ctx)
	if err := logging.Init(ctx, sessionID); err != nil {
		// Init failed - logging will use stderr fallback
		return func() {}
	}

	// Configure redaction once at startup: PII (opt-in), inline custom_redactions,
	// and rule packs discovered under .entire/redactors/. No-op if nothing is configured.
	strategy.EnsureRedactionConfigured()

	return logging.Close
}

