package strategy

import (
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// TestInstallGitHook_ConcurrentInstallPreservesUserHook pins that two hook
// processes entering the install at the same moment cannot lose a pre-existing
// user hook.
//
// The backup step is a read -> rename -> write with no lock across it: A reads
// the user hook, renames it to commit-msg.pre-entire and writes its wrapper;
// B, still holding a read from before that rename, sees no marker and no
// backup and renames the path again — but by then the path holds A's wrapper,
// and rename(2) overwrites the destination. The user hook is then gone from
// both files and the installed hook chains to a copy of itself, so every later
// `git commit` re-executes it until a process or CPU limit.
//
// The two assertions cover both losing interleavings: the backup must still be
// the user's hook (not an Entire wrapper), and the installed hook must chain to
// that backup (otherwise the hook is orphaned and silently never runs again).
//
// Concurrency makes this probabilistic per round, so it runs many rounds: the
// interleaving reproduces in roughly 40% of rounds at this installer count,
// leaving a false-pass chance below 1e-5 across the round count. A correct
// implementation cannot corrupt, so the test is stable once fixed.
//
// No t.Parallel: t.Chdir plus the package-level hooks-dir and worktree-root
// caches are process-global.
func TestInstallGitHook_ConcurrentInstallPreservesUserHook(t *testing.T) {
	const (
		rounds     = 24
		installers = 8
		userHook   = "#!/bin/sh\necho USER_HOOK_RAN\n"
		hookName   = "commit-msg"
	)

	corrupted := 0
	for round := range rounds {
		dir := t.TempDir()
		testutil.InitRepo(t, dir)

		hooksDir := filepath.Join(dir, ".git", "hooks")
		if err := os.MkdirAll(hooksDir, 0o755); err != nil {
			t.Fatalf("round %d: create hooks dir: %v", round, err)
		}
		//nolint:gosec // a git hook must be executable to be exercised at all
		if err := os.WriteFile(filepath.Join(hooksDir, hookName), []byte(userHook), 0o755); err != nil {
			t.Fatalf("round %d: seed user hook: %v", round, err)
		}

		t.Chdir(dir)
		ClearHooksDirCache()
		paths.ClearWorktreeRootCache()

		var wg sync.WaitGroup
		for range installers {
			wg.Add(1)
			go func() {
				defer wg.Done()
				// The return values are deliberately dropped: a losing
				// installer may legitimately fail its own rename. What must
				// hold is the state of the files afterwards, asserted below.
				_, _ = InstallGitHook(t.Context(), true, false, false)
			}()
		}
		wg.Wait()

		backupName := hookName + backupSuffix
		backup, err := os.ReadFile(filepath.Join(hooksDir, backupName))
		switch {
		case err != nil:
			corrupted++
			t.Errorf("round %d: user hook not preserved — reading %s: %v", round, backupName, err)
		case strings.Contains(string(backup), entireHookMarker):
			corrupted++
			t.Errorf("round %d: user hook DESTROYED — %s holds Entire's own wrapper, so the installed hook chains to a copy of itself and every commit re-executes it",
				round, backupName)
		case string(backup) != userHook:
			corrupted++
			t.Errorf("round %d: %s holds neither the user hook nor an Entire wrapper:\n%s", round, backupName, backup)
		}

		installed, err := os.ReadFile(filepath.Join(hooksDir, hookName))
		if err != nil {
			t.Fatalf("round %d: read installed hook: %v", round, err)
		}
		if !strings.Contains(string(installed), backupName) {
			corrupted++
			t.Errorf("round %d: installed %s does not chain to %s — the user hook is orphaned and never runs again", round, hookName, backupName)
		}
	}

	if corrupted > 0 {
		t.Logf("%d of %d rounds corrupted with %d concurrent installers", corrupted, rounds, installers)
	}
}

package strategy

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// TestInstallGitHook_ConcurrentInstallPreservesUserHook pins that two hook
// processes entering the install at the same moment cannot lose a pre-existing
// user hook.
//
// The backup step is a read -> rename -> write with no lock across it. A reads
// the user hook, renames it to <hook>.pre-entire and writes its wrapper; B,
// still holding a read from before that rename, sees no marker and no backup
// and renames the path again — but by then the path holds A's wrapper, and
// rename(2) overwrites the destination. The user hook is then gone from both
// files and the installed hook chains to a copy of itself, so every later git
// operation on that hook re-executes it until a process or CPU limit.
//
// Two assertions per hook cover both losing interleavings: the backup must
// still be the user's script (not an Entire wrapper), and the installed hook
// must chain to that backup — otherwise the user's hook is orphaned and
// silently never runs again.
//
// Every hook spec is seeded, so each round gets one independent chance to
// interleave per spec. Detection is still probabilistic per round; the round
// count is sized so the test fails even on a single-CPU runner (measured
// per-round rates: ~85% at GOMAXPROCS=4, ~35% at 2, ~20% at 1, all under
// -race). A correct implementation cannot corrupt, so the test is stable once
// this is fixed.
//
// No t.Parallel: t.Chdir plus the package-level hooks-dir and worktree-root
// caches are process-global.
func TestInstallGitHook_ConcurrentInstallPreservesUserHook(t *testing.T) {
	const (
		rounds     = 40
		installers = 4
	)

	prefix, err := hookCmdPrefix(false, false)
	if err != nil {
		t.Fatalf("hookCmdPrefix: %v", err)
	}
	specs := buildHookSpecs(prefix)
	if len(specs) == 0 {
		t.Fatal("no hook specs to install")
	}
	userHook := func(name string) string {
		return fmt.Sprintf("#!/bin/sh\necho USER_HOOK_%s\n", name)
	}

	corrupted := 0
	for round := range rounds {
		dir := t.TempDir()
		testutil.InitRepo(t, dir)

		hooksDir := filepath.Join(dir, ".git", "hooks")
		if err := os.MkdirAll(hooksDir, 0o755); err != nil {
			t.Fatalf("round %d: create hooks dir: %v", round, err)
		}
		for _, spec := range specs {
			//nolint:gosec // a git hook must be executable to be exercised at all
			if err := os.WriteFile(filepath.Join(hooksDir, spec.name), []byte(userHook(spec.name)), 0o755); err != nil {
				t.Fatalf("round %d: seed user %s: %v", round, spec.name, err)
			}
		}

		t.Chdir(dir)
		ClearHooksDirCache()
		paths.ClearWorktreeRootCache()

		var wg sync.WaitGroup
		for range installers {
			wg.Add(1)
			go func() {
				defer wg.Done()
				// Return values are deliberately dropped: a losing installer
				// may legitimately fail its own rename. What must hold is the
				// state of the files afterwards, asserted below.
				_, _ = InstallGitHook(t.Context(), true, false, false)
			}()
		}
		wg.Wait()

		for _, spec := range specs {
			backupName := spec.name + backupSuffix
			backup, err := os.ReadFile(filepath.Join(hooksDir, backupName))
			switch {
			case err != nil:
				corrupted++
				t.Errorf("round %d: user %s not preserved — reading %s: %v", round, spec.name, backupName, err)
			case strings.Contains(string(backup), entireHookMarker):
				corrupted++
				t.Errorf("round %d: user %s DESTROYED — %s holds Entire's own wrapper, so the installed hook chains to a copy of itself and re-executes it until a process limit",
					round, spec.name, backupName)
			case string(backup) != userHook(spec.name):
				corrupted++
				t.Errorf("round %d: %s holds neither the user hook nor an Entire wrapper:\n%s", round, backupName, backup)
			}

			installed, err := os.ReadFile(filepath.Join(hooksDir, spec.name))
			if err != nil {
				t.Fatalf("round %d: read installed %s: %v", round, spec.name, err)
			}
			if !strings.Contains(string(installed), backupName) {
				corrupted++
				t.Errorf("round %d: installed %s does not chain to %s — the user hook is orphaned and never runs again",
					round, spec.name, backupName)
			}
		}
	}

	if corrupted > 0 {
		t.Logf("%d corrupted hooks across %d rounds of %d concurrent installers", corrupted, rounds, installers)
	}
}

