			}
		}

		t.Chdir(dir)
		ClearHooksDirCache()
		paths.ClearWorktreeRootCache()

		var wg sync.WaitGroup
		for range installers {
			wg.Add(1)
			go func() {
				defer wg.Done()
				// Return values are deliberately dropped: a losing installer
				// may legitimately fail its own rename. What must hold is the
				// state of the files afterwards, asserted below.
				_, _ = InstallGitHook(t.Context(), true, false, false)
			}()
		}
		wg.Wait()

		for _, spec := range specs {
			backupName := spec.name + backupSuffix
			backup, readErr := os.ReadFile(filepath.Join(hooksDir, backupName))
			switch {
			case readErr != nil:
				corrupted++
				t.Errorf("round %d: user %s not preserved — reading %s: %v", round, spec.name, backupName, readErr)
			case strings.Contains(string(backup), entireHookMarker):
				corrupted++
				t.Errorf("round %d: user %s DESTROYED — %s holds Entire's own wrapper, so the installed hook chains to a copy of itself and re-executes it until a process limit",
					round, spec.name, backupName)
			case string(backup) != userHook(spec.name):
				corrupted++
				t.Errorf("round %d: %s holds neither the user hook nor an Entire wrapper:\n%s", round, backupName, backup)
			}

			installed, readErr := os.ReadFile(filepath.Join(hooksDir, spec.name))
			if readErr != nil {
				t.Fatalf("round %d: read installed %s: %v", round, spec.name, readErr)
			}
			if !strings.Contains(string(installed), backupName) {
				corrupted++
				t.Errorf("round %d: installed %s does not chain to %s — the user hook is orphaned and never runs again",
					round, spec.name, backupName)
			}
		}
	}

	if corrupted > 0 {
		t.Logf("%d corrupted hooks across %d rounds of %d concurrent installers", corrupted, rounds, installers)
	}
}
